def clean_and_forecast_canteen_data(raw_records, capacity_min=50, capacity_max=300):
    """
    Cleans raw noisy telemetry, removes invalid strings & impossible outliers,
    and returns sanitized data alongside statistical intelligence.
    """
    cleaned = []
    dropped_count = 0

    for item in raw_records:
        try:
            val = float(str(item).strip())
            if capacity_min <= val <= capacity_max:
                cleaned.append(val)
            else:
                dropped_count += 1
        except (ValueError, TypeError):
            dropped_count += 1

    if not cleaned:
        return {"error": "Insufficient valid data points"}

    avg_demand = sum(cleaned) / len(cleaned)
    max_demand = max(cleaned)
    min_demand = min(cleaned)

    # 10% safety buffer for resilient procurement
    recommended_procurement = round(avg_demand * 1.10)

    return {
        "valid_count": len(cleaned),
        "dropped_anomalies": dropped_count,
        "mean_demand": round(avg_demand, 2),
        "demand_range": (min_demand, max_demand),
        "target_procurement": recommended_procurement
    }

# Simulated noisy data from canteen turnstiles
raw_feed = ["140", 165, "None", 2999, 155, -20, " 180 ", 172, "FAULT", 160]

report = clean_and_forecast_canteen_data(raw_feed)
print("=== CANTEEN DATA-TO-INTELLIGENCE REPORT ===")
for k, v in report.items():
    print(f"{k:<20}: {v}")

import math

def dot_product(v1, v2):
    """Calculates scalar dot product of two vectors."""
    return sum(a * b for a, b in zip(v1, v2))

def vector_magnitude(v):
    """Calculates Euclidean L2 norm of a vector."""
    return math.sqrt(sum(x ** 2 for x in v))

def cosine_similarity(v1, v2):
    """Computes angular cosine similarity between two non-zero vectors."""
    mag1 = vector_magnitude(v1)
    mag2 = vector_magnitude(v2)
    if mag1 == 0 or mag2 == 0:
        return 0.0
    return dot_product(v1, v2) / (mag1 * mag2)

# Digital Library Corpus: Features represent [Space, Physics, History, Biology]
documents = [
    {"title": "Orbital Mechanics for Beginners",      "vector": [9.0, 8.0, 1.0, 0.0]},
    {"title": "The Fall of the Roman Empire",         "vector": [0.0, 0.0, 9.5, 1.0]},
    {"title": "Cellular Respiration and Mitochondria", "vector": [0.0, 2.0, 0.5, 9.0]},
    {"title": "Astrophysics and Cosmic Origins",      "vector": [8.5, 9.0, 2.0, 0.0]}
]

# Student Search Query: "Deep space rocket physics" -> Vectorized as [8.0, 7.0, 0.5, 0.0]
query_vector = [8.0, 7.0, 0.5, 0.0]

print("=== VECTOR SEMANTIC SEARCH RESULTS ===")
search_results = []
for doc in documents:
    score = cosine_similarity(query_vector, doc["vector"])
    search_results.append({"title": doc["title"], "score": round(score, 4)})

# Rank descending by similarity score
search_results.sort(key=lambda x: x["score"], reverse=True)

for rank, item in enumerate(search_results, 1):
    print(f"Rank {rank}: [Similarity {item['score']:.4f}] - {item['title']}")

def evaluate_stream_selection(math_interest, tech_coding, humanities_arts, business_econ):
    """
    Evaluates student academic preferences (rated 1-10) and suggests optimal
    Class 11-12 subject streams and higher education trajectories.
    """
    stream_scores = {
        "Science_PCM_CS": (math_interest * 0.4) + (tech_coding * 0.5) + (humanities_arts * 0.1),
        "Commerce_Math_Analytics": (business_econ * 0.5) + (math_interest * 0.3) + (tech_coding * 0.2),
        "Humanities_Math_Cognitive": (humanities_arts * 0.5) + (math_interest * 0.3) + (tech_coding * 0.2),
        "Design_Media_Technology": (humanities_arts * 0.4) + (tech_coding * 0.3) + (business_econ * 0.3)
    }

    top_stream = max(stream_scores, key=stream_scores.get)

    recommendations = {
        "Science_PCM_CS": {
            "subjects": "Physics, Chemistry, Mathematics, Computer Science / AI",
            "degrees": "B.Tech/B.S. in CS, Artificial Intelligence, Robotics",
            "careers": "Machine Learning Engineer, Robotics Systems Architect"
        },
        "Commerce_Math_Analytics": {
            "subjects": "Economics, Mathematics, Accountancy, Business Studies / Informatics",
            "degrees": "B.S. in Data Analytics, Quantitative Finance, Business Analytics",
            "careers": "Fintech Data Scientist, AI Supply Chain Analyst"
        },
        "Humanities_Math_Cognitive": {
            "subjects": "Psychology, Sociology / Literature, Mathematics, Political Science",
            "degrees": "B.A./B.S. in Cognitive Science, Computational Linguistics, AI Ethics",
            "careers": "AI Safety Researcher, NLP Prompt Architect, AI Policy Counsel"
        },
        "Design_Media_Technology": {
            "subjects": "Fine Arts, Media Studies, Applied Math / Informatics, English",
            "degrees": "B.Des in Digital Product Design, Human-Computer Interaction",
            "careers": "AI Experience Designer, Synthetic Media Creative Director"
        }
    }

    return top_stream, stream_scores[top_stream], recommendations[top_stream]

